    Console.WriteLine($"Ctor: ({string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");
foreach (var p in t2.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly))
    Console.WriteLine($"Prop: {p.PropertyType.Name} {p.Name}");

Console.WriteLine("---MapMcp extension methods---");
var aspAsm = typeof(ModelContextProtocol.AspNetCore.HttpServerTransportOptions).Assembly;
